NAME = 'GerOffBiSt: Offene Bibel - Studienfassung'
BOOK = 'Acts'

CHAPTERS = {
    1: {
        1: 'Das erste Buch {zwar} habe ich (gemacht =) verfasst von allem, (o) lieber Theophilos, was Jesus {begann} tat und lehrte,',
        2: 'bis zu dem Tag, als er entrückt (in die Höhe genommen, aufgenommen) wurde, nachdem er den Aposteln, die er ausgewählt hatte, durch den heiligen Geist Anweisungen gab (befahl).',
        3: 'Ihnen erwies er sich {auch} als lebendig (Lebender) nach seinem Sterben durch viele Beweise. Während vierzig Tagen erschien er ihnen und sprach zu ihnen über das (König) Reich Gottes.',
        4: 'Und während (als) er mit ihnen (zusammensaß) zusammen aß, befahl er ihnen, nicht von Jerusalem fortzugehen, sondern die Verheißung des Vaters zu erwarten, „die ihr von mir gehört habt.',
        5: 'Denn Johannes hat {zwar} mit Wasser getauft, ihr aber werdet mit heiligem Geist getauft werden (nicht lange nach diesen Tagen =) in wenigen Tagen“.',
        6: 'Die {zwar} nun zusammengekommen waren, fragten ihn {und sprachen}: „Herr, wirst du (zu dieser Zeit =) jetzt die Königsherrschaft für Israel wiederherstellen?“',
        7: 'Er aber sprach zu ihnen: „Euch ist nicht [gegeben], die Zeiträume oder Zeitpunkte zu kennen, die der Vater in seiner (Voll) Macht festgelegt hat,',
        8: 'aber (sondern) ihr sollt (werdet) die Kraft (Macht) des heiligen Geistes empfangen, der über euch kommen wird, und ihr sollt (werdet) meine Zeugen sein sowohl in Jerusalem als auch in ganz Judäa und Samarien und bis zum fernsten Land (Ende der Erde) “.',
        9: 'Und nachdem er dies gesagt hatte, sahen sie, wie (dass) er aufgehoben wurde und eine Wolke ihn vor ihren Augen verbarg.',
        10: 'Und während sie gespannt in den Himmel blickten, wohin er gegangen war, da, (siehe =) plötzlich, standen zwei Männer bei ihnen in weißer Kleidung (weißen Gewändern),',
        11: 'die {auch} sprachen: „Ihr Galiläer, was steht ihr da und schaut zum Himmel? Dieser Jesus, der von euch in den Himmel aufgenommen wurde, wird so [wieder] kommen, (auf welche Weise =) wie ihr ihn in den Himmel gehen saht“.',
        12: 'Dann kehrten sie nach Jerusalem zurück vom Berg, der Ölberg genannt wird, der ist nahe bei Jerusalem, einen Sabbatweg.',
        13: 'Und als sie hineinkamen, stiegen sie zum Obergemach hinauf, wo sie sich gewöhnlich aufhielten, Petrus {und}, Johannes {und}, Jakobus und Andreas, Philippus und Thomas, Bartholomäus und Matthäus, Jakobus Alphaios, Simon, der Zelot (Eiferer) und Judas, [der Sohn] des Jakobus.',
        14: 'Diese alle blieben beharrlich beim Gebet mit den Frauen und Maria, der Mutter Jesu, und seinen Brüdern.',
        15: 'Und in jenen Tagen stellte sich Petrus in die Mitte der Brüder [und] sprach – es war {auch} die Menge der Namen (Personen) [in der] Gemeinschaft (?, beisammen) ungefähr 120 –:',
        16: 'Liebe Brüder, es musste die Schrift erfüllt werden, die der Heilige Geist vorhersagte (im voraus sagte) durch den Mund Davids über Judas, der zum Führer der Häscher (Greifer) Jesu wurde,',
        17: 'denn er gehörte zu uns und empfing den Lohn dieses Dienstes.',
        18: 'Dieser nämlich kaufte einen Acker vom (Lohn der Ungerechtigkeit =) ungerechten Lohn, und als er vornüber stürzte, zerbarst er krachend in der (Leibes) Mitte, und seine Eingeweide quollen heraus (ergossen sich).',
        19: '{Und} das wurde allen Bewohnern Jerusalems bekannt, sodass jener Acker in ihrer eigenen Sprache „Akeldamach“genannt wird, das bedeutet Blutacker.',
        20: 'Denn es steht im Psalmbuch {geschrieben}: „Sein Gehöft soll wüst werden und (es soll keiner sein, der in ihm wohnt =) keiner mehr in ihm wohnen“, und: „sein Aufsichtsamt soll ein anderer empfangen“.',
        21: 'Es muss nun von allen den Männern, die mit uns gegangen sind in all der Zeit, in der ausging und einging bei uns der Herr Jesus,',
        22: 'angefangen von der Taufe des Johannes bis zu dem Tag als er von uns weg aufgenommen wurde, einer von diesen (muss) Zeuge seiner Auferstehung mit uns werden.',
        23: 'Und sie stellen zwei, Joseph der Barnabas genannte, der den Beinamen Justus hat, und Matthias.',
        24: 'Und nachdem sie gebetet hatten, sprachen sie: Du Herr, der Herzenskenner aller, zeige von diesen zweien einen, den du ausgewählt hast.',
        25: 'damit er in Empfang nimmt das Amt dieses Dienstes und das Apostelamt von dem Judas zur Seite getreten ist um zu seinem eigenen Ort zu gehen.',
        26: 'Und sie gaben ihnen Lose und das Los fiel auf Matthias und wurde inmitten der elf Apostel hinzugestellt.',
    },
    2: {
        1: 'Und als sich der Tag des Wochenfests erfüllte (zu Ende ging), waren alle zusammen [als] Gemeinschaft (?, beisammen).',
        2: 'Und plötzlich kam (entstand; ereignete sich) vom Himmel her ein Geräusch (Lärm) wie das Wehen eines heftigen Windes und füllte das ganze Haus, in dem sie [gerade] saßen',
        3: 'und ihnen erschienen sich verteilende (teilende) Zungen wie [von] Feuer und sie setzten sich auf einen jeden von ihnen',
        4: 'und alle wurden mit heiligen Geist erfüllt und begannen, [so] [in] anderen Zungen zu sprechen, wie der Geist ihnen zu prophezeien (äußern) eingab.',
        5: 'Es hielten sich [gerade] auf (wohnten) {aber} Juden in Jerusalem, fromme Männer aus allen Völkern unter dem Himmel,',
        6: '[und] als {aber} dieses Getön entstand, kam die Menge zusammengelaufen und war bestürzt (verstört, verwirrt), denn ein jeder hörte sie in der eigenen Sprache sprechen.',
        7: 'Sie (Alle) waren {aber} außer sich (fassungslos, erstaunt) und wunderten (erstaunten) sich, [indem sie] sagten: „Siehe! Sind nicht alle diese Sprechenden Galiläer?',
        8: 'Und wie hören wir [sie dann] jeder in unserer eigenen Sprache, in der wir geboren wurden?',
        9: '[Wir sind ja] Parther und Meder und Elamiter und die Bewohner von Mesopotamien, vom Judäischen und auch Kappadozien, von Pontus und Asien,',
        10: 'von Phrygien und auch Pamphylien, von Ägypten und den Gebieten Lybiens um Zyrene, und die sich [hier] aufhaltenden Römer,',
        11: 'Juden und auch Proselyten, Kreter und Araber - wir hören sie in unseren Zungen die Großtaten Gottes rühmen!“',
        12: 'Alle waren {aber} außer sich (fassungslos, erstaunt) und ratlos, [indem] sie zueinander sagten: „Was mag dies sein!?“',
        13: 'Andere aber sagten spottend: „Mit Traubensaft (Wein?) sind sie voll (angefüllt)!“',
        14: 'Petrus jedoch stellte sich mit den [anderen] Elf hin, erhob seine Stimme und prophezeite (äußerte) ihnen: „ [Liebe] Judäer (Juden) und all [ihr] euch in Jerusalem Aufhaltenden (all [ihr] Wohnenden)! Dies sei euch bekannt, {und} vernehmt meine Worte!',
        15: 'Diese sind nämlich nicht, wie ihr annehmt, betrunken – es ist ja (nämlich) [erst] die dritte Stunde des Tages –,',
        16: 'sondern: Dies ist das durch den Propheten Joel Vorhergesagte:',
        17: '»»Und es wird sein in den Letzten Tagen:« – sagt Gott – »Ich werde ausgießen [etwas] von meinem Geist auf alles Fleisch,Und prophezeien werden eure Söhne und eure Töchter Und eure jungen [Menschen] werden Visionen sehenUnd eure alten [Menschen] werden durch Träume träumen.',
        18: 'Und auch (selbst) auf meine Sklaven und auf meine Sklavinnen werde ich in jenen Tagen [etwas] von meinem Geist ausgießenUnd sie werden prophezeien.',
        19: 'Und ich werde darbieten Wunder im Himmel drobenUnd Zeichen auf der Erde drunten:Blut und Feuer und Rauchqualm.',
        20: 'Die Sonne wird verwandelt werden zu FinsternisUnd der Mond zu BlutVor dem Kommen des Tags des Herrn, des großen und sichtbaren (prachtvollen).',
        21: '{Und es wird sein:} Jeder, der den Namen des Herrn anruft, wird gerettet werden.««',
        22: '[Liebe] Israeliten, hört diese Worte: Jesus, den Nazoräer, einen von Gott für euch beglaubigten (bestellten) Mann durch [die] Machttaten und Wunder und Zeichen, welche Gott durch ihn in eurer Mitte vollbracht hat – wie ihr [ja selbst] wisst –',
        23: 'diesen [euch] – wegen dem beschlossenen (festgesetzten) Plan und dem Vorauswissen Gottes! – Ausgelieferten habt ihr getötet, indem [ihr ihn] durch Hände Gesetzloser [ans Kreuz] geschlagen [habt];',
        24: '[ihn,] den Gott auferstehen ließ, indem er die Geburtswehen (Fesseln?) des Todes löste, weil es nicht möglich war, dass er unter ihm gehalten wurde.',
        25: 'Denn David sagt über ihn: »Ich hatte den Herrn vor mir vor Augen durch alle [Zeit],Weil er zu meiner Rechten ist, damit ich nicht wanken werde.',
        26: 'Darum freute sich mein HerzUnd jubelte meine ZungeUnd noch dazu wird mein Fleisch sich niederlassen (zelten) aufgrund [meiner] Zuversicht (Hoffnung),',
        27: 'Weil du meine Seele nicht dem Hades überlassen (im Hades zurücklassen) wirstUnd nicht zulassen wirst, dass dein Heiliger Verwesung erfährt.',
        28: 'Du hast mir die Wege des Lebens kundgetan,Du wirst mich erfüllen mit Freude vor deinem Gesicht.«',
        29: '[Liebe] Brüder, man kann mit Freimut (Offenheit) zu euch über den Patriarchen David sprechen – [nämlich darüber,] dass er sowohl starb als auch begraben wurde, und [dass] seine Grabstätte bis zu diesem Tage bei uns ist.',
        30: 'Weil er nun ein Prophet war und wusste, dass Gott ihm mit einem Eid geschworen hatte, [jemanden] aus der Frucht seiner Lende auf seinen Thron zu setzen,',
        31: 'sprach er im Vorhinein über die Auferstehung des Christus – [nämlich,] dass er weder dem Hades überlassen werden würde (im Hades zurückgelassen werden würde) noch sein Fleisch Verwesung erfahren würde.',
        32: 'Diesen Jesus hat Gott auferstehen lassen, wofür wir alle Zeugen sind.',
        33: 'Nachdem er nun zur Rechten (durch die rechte Hand) Gottes erhöht worden war und auch den verheißenen Heiligen Geist (die Verheißung des Heiligen Geistes) vom Vater empfangen hatte, goß er diesen aus, was (den) ihr sowohl seht als auch hört.',
        34: 'Denn nicht David ist in den Himmel hinaufgestiegen; stattdessen sagt er selbst: »Es sagte der Herr zu meinem Herrn: »Sitze (Setze dich) zu meiner Rechten,',
        35: 'bis ich deine Feinde zum Schemel für deine Füße mache!««',
        36: 'Mit Sicherheit sei nun dem ganzen Haus Israel bekannt, dass Gott ihn sowohl zum Herrn als auch zum Christus gemacht hat – diesen Jesus, den ihr gekreuzigt habt!',
        37: 'Als sie {aber} [dies] hörten, wurden sie im Herz durchbohrt. Sie sagten auch zu Petrus und den übrigen Aposteln: »Was sollen wir tun, [liebe] Brüder?«',
        38: 'Petrus {aber} [antwortete] ihnen: »Denkt um!«, {sagt[e] er,} »und es lasse sich taufen ein jeder von euch auf den Namen Jesu Christi zur Vergebung der Sünden von euch! Und ihr werdet empfangen das Geschenk, [das] der Heilige Geist [ist].',
        39: "''Euch'' nämlich gilt die Verheißung und euren Kindern, und allen, die fern [sind], wie viele auch hinzurufen mag der Herr, unser Gott.«",
        40: 'Auch mit anderen weiteren Worten legte er Zeugnis ab und mahnte sie {indem er sagte}: »Lasst euch retten aus diesem verkehrten Geschlecht!«',
        41: 'Diejenigen nun, die seine Rede annahmen, ließen sich taufen und so wurden an jenem Tag etwa 3000 Seelen hinzugefügt.',
        42: 'Sie hielten {aber} [beständig sehr] fest an der Lehre der Apostel und an der Gemeinschaft, (dem gemeinschaftlichen Brotbrechen) dem Brotbrechen und den Gebeten.',
        43: '[Und] es war (da entstand) {aber} Ehrfurcht (Furcht) in allen Seelen; es geschahen sowohl viele Wunder als auch Zeichen durch die Apostel.',
        44: '{Aber} alle Glaubenden {waren} [als] Gemeinschaft (?, zusammen) {und} sie hatten alles gemeinsam:',
        45: '{Und} [immer wieder] verkauften sie die Habe und die Besitztümer und verteilten sie an alle, wie jemand Bedarf hatte.',
        46: 'Indem sie sich täglich einmütig (einträchtig) im Tempel aufhielten und im Haus Brot brachen, nahmen sie Speise in Jubel und Schlichtheit des Herzens (jubelnd und mit lauterem Herzen) zu sich;',
        47: 'sie lobten Gott und hatten Ansehen beim (waren gefällig dem) ganzen Volk. [Und] der Herr {aber} fügte täglich Gerettete hinzu zur Gemeinschaft (?, zusammen?). “',
    },
    4: {
        8: 'Da sprach Petrus, erfüllt mit heiligem Geist, zu ihnen: Oberste des Volkes und Älteste!',
        9: 'Wenn wir heute über die Wohltat an einem kranken Menschen geprüft werden, durch welches er gerettet worden ist,',
        10: 'so sei euch allen und dem ganzen Volk Israel bekannt: Im Namen Jesu Christi, des Nazoräers, den ihr gekreuzigt habt, den Gott auferweckt hat aus den Toten - in diesem Namen steht er vor euch gesund.',
        11: 'Das ist der Stein, der, von euch, den Bauleuten, verachtet, zum Eckstein geworden ist.',
        12: 'Und es ist in gar keinem anderen das Heil, denn auch kein anderer Name ist unter dem Himmel, gegeben den Menschen, in den wir gerettet werden müssen.',
        13: 'Als sie aber die Kühnheit des Petrus und Johannes sahen und bemerkten, dass es ungelehrte Menschen seien und ungebildet, verwunderten sie sich und sie erkannten von ihnen, dass sie mit Jesus gewesen waren.',
        14: 'Und als sie den Menschen, der geheilt worden war, bei ihnen stehen sahen, hatten sie nichts dagegen zu sagen.',
        32: 'Die Menge der Glaubenden aber was ein Herz und eine Seele und nicht einer sagte, etwas von dem Verhandenen sei sein Eigen, sondern es war ihnen alles gemeinsam.',
        33: 'Und mit großer Kraft legten die Apostel das Zeugnis der Auferstehung des Herrn Jesus ab und große Gnade war mit ihnen allen.',
        34: 'Es war nämlich nicht einer bedürftig bei ihnen. Denn es befanden sich soviele Grund- oder Hausbesitzer unter ihnen. Nahcdem sie verkauft hatten, brachten sie die Verkaufssumme des Verkauften.',
    },
    5: {
        1: 'Da war ein Mann namens Hananias und seine Frau Saphira. Er verkaufte ein Grundstück',
        2: 'und behielt etwas von dem Erlös für sich und seine Frau wusste davon. Dann nahm er den [übrigen] Teil und gab ihn den Aposteln.',
        3: 'Da sagte Petrus: „Hananias, warum hat der Satan dein Herz erfüllt, den Heiligen Geist zu belügen und einen Teil von dem Erlös des Feldes für dich zu behalten?',
        4: 'Ist es nicht so, dass es dir gehören würde, wenn du es nicht verkauft hättest? Und [selbst] als du es verkauft hattest, stand [das Geld] nicht dir zur Verfügung? Wieso hast du dir diese Sache {in deinem Herzen} vorgenommen? Du hast nicht Menschen belogen, sondern Gott!“',
        5: 'Als Hananias das hörte, fiel er um und starb. Alle, die davon hörten, hatten große Angst.',
        12: 'Durch aber die Hände der Apostel geschahen viele Zeichen und Wunder unter (in) dem Volk. Und einmütig waren alle [zusammen (versammelt)] in der Säulenhalle (Stoa) Salomos.',
        13: 'Von den übrigen aber wagte keiner, sich ihnen anzuschließen, aber das Volk pries sie.',
        14: 'Darüber hinaus (Mehr noch) aber (: es) wurden Gläubige dem Herrn hinzugefügt, eine Menge von Männern und Frauen,',
        15: 'so dass sie auch auf (in) die Plätze (Straßen) die Kranken hinaustrugen und sie auf Betten und Bahren (Pritschen) legten, damit, wenn Petrus kommt, wenigstens (und wenn auch [nur]) der Schatten einen von ihnen beschatte.',
        16: 'Es kam aber auch die Menge der umliegenden Städte Jerusalems (der um Jerusalem liegenden Städte) und brachte Kranke und von unreinen Geistern Bedrängte, welche alle geheilt wurden.',
    },
    6: {
        8: 'Stephanus aber, angefüllt mit Gnade und Kraft, tat große Wunder und Zeichen im volk.',
        9: 'Es standen aber einige auf aus der sogenannten der Libertiner und Kyrener und Alexandiner und aus Kilikien und Asien, um mit Stephanus zu streiten (oder Beiordnung: und stritten mit Stephanus)',
        10: 'Aber sie konnten der Weisheit und dem Geist, mit dem er sprach, nicht widerstehen.',
        11: 'Dann stifteten sie Männer an zur Aussage: Wir haben gehört, wie du gesagt hast blasphemische (gotteslästerliche/lügenhafte) Worte gegen Mose und Gott.',
        12: 'Und sie hetzten das Volk auf und die Ältesten und die Schriftgelehrten und als sie hinzugetreten waren, packten sie ihn und führten in vor den Hohen Rat (Synhedrion).',
        13: 'Und sie stellten falsche Zeugen auf, die sagen: Dieser Mensch hört nicht auf, Worte zu sagen gegen diesen heiligen Ort und das Gesetz.',
        14: 'Wir haben nämlich gehört, wie er sagte: Dieser Jesus von Nazareth wir diesen Ort zerstören und verändern die Bräuche, die uns Mose gegeben hat.',
        15: 'Und als alle, die im Hohen rat (Synhedrion) saßen, ihn anschauten, sahen sie sein Gesicht wie das Gesicht eines Engels.',
    },
    8: {
        26: 'Der (ein) Engel des Herrn aber sprach zu Philippus {folgendermaßen}: „Steh auf und geh nach Süden auf dem Weg, der herabkommt von Jerusalem nach Gaza; er ist menschenleer.“',
        27: 'Und er stand auf und ging [los]. {Und} sieh da!, ein äthiopischer Mann, ein Eunuch, Hofbeamter (fürstlicher Beamter) der Kandake, der Königin der Äthiopier, der über alle ihre Schätze [gesetzt] war, der nach Jerusalem gekommen war, um anzubeten,',
        28: '{und} war auf dem Rückweg und saß auf seinem Wagen und las den Propheten Jesaja.',
        29: 'Der [Heilige] Geist aber sprach zu Philippus: geh hin (trete hinzu) und hänge dich an (folge dicht) diesen Wagen.',
        30: 'Als Philippus {aber} hingegangen war, hörte er, wie er (dass er) den Propheten Jesaja las und sprach: „Verstehst du denn auch, was du liest?“',
        31: 'Der aber sprach (antwortete): Wie soll ich [dazu] in der Lage sein, wenn mich keiner anleitet? Und er bat Philippus, aufzusteigen und sich zu ihm zu setzen.',
        32: 'Der Abschnitt der Schrift, den er las, war dieser: „Wie ein Schaf wurde er zur Schlachtung gebracht (geführt), und so, wie ein Lamm vor dem Scherer stumm [ist] (verstummt), so öffnet er seinen Mund nicht.“',
        33: 'In seiner Erniedrigung wurde das Urteil gegen ihn aufgehoben. Wer von seinem Geschlecht wird davon erzählen? Denn sein Leben ist von der Erde weggenommen.',
        34: 'Der Eunuch aber antwortete Philippus {und sprach}: Ich bitte dich, von wem sagt der Prophet das? Von ihm selbst, oder von einem anderen?',
        35: 'Philippus aber öffnete seinen Mund und begann von dieser Schrift [stelle] aus, ihm Jesus zu evangelisieren (verkündigen).',
        36: 'Wie sie aber den Weg entlangfuhren (weiterzogen), kamen sie an ein Wasser, und der Eunuch sprach: Sieh mal, Wasser! Was verbietet, dass du mich taufst?',
        38: 'Und er befahl den Wagen zu stoppen (anzuhalten), und beide stiegen ins Wasser, Philippus und {auch} der Eunuch, und er taufte ihn.',
        39: 'Als er aber aus dem Wasser stieg (auftauchte), entführte (entrückte) der Geist des Herrn den Philippus, und der Eunuch sah ihn nicht mehr. Er reiste (zog) aber seinen Weg freudig.',
        40: 'Philippus aber wurde in Asdod gefunden. Und er zog durch alle Städte und evangelisierte (verkündigte), bis er nach Cäsarea kam.',
    },
    16: {
        1: 'Er kam aber auch nach Derbe und Lystra. {Und siehe} dort war ein Jünger (Schüler) namens Timotheus, Sohn einer gläubigen Jüdin, sein Vater aber [war] Grieche,',
        2: 'der hatte einen guten Ruf bei den Brüdern (Geschwistern) in Lystra und Ikonium.',
        3: 'Von diesem wollte Paulus, dass er mit ihm hinauszöge, und er nahm ihn mit und beschnitt ihn wegen der Juden, die an jenen Orten waren; denn alle wussten, dass sein Vater Grieche war.',
        4: 'Als sie {aber} die Städte durchzogen, übergaben sie ihnen zur Beachtung (= hielten sie sie an, sich zu richten nach) die Gebote, die von den Aposteln und Ältesten in Jerusalem festgelegt (beschlossen) worden waren.',
        5: 'Die Gemeinden {nun zwar} wurden fest im Glauben und nahmen täglich zu an Zahl.',
        6: 'Als sie aber durch das Phrygische und Galatische Gebiet zogen, wurden sie vom heiligen Geist abgehalten (daran gehindert, wurde es ihnen verboten), das Wort in der [Provinz] Asien zu predigen (aussprechen, verkündigen).',
        7: 'Nachdem sie aber in die Gegend von Mysien gekommen (gelangt, gereist) waren, versuchten sie, nach Bithynien zu reisen, aber der Geist Jesu verwehrte ihnen das.',
        8: 'Nachdem sie {aber} an Mysien vorbeigezogen waren, stiegen sie hinab nach Troas.',
        9: 'Aber {und} nachts erschien Paulus eine Vision (ein Gesicht), ein makedonischer Mann stand da {und} bat ihn und sprach: Setze über nach Makedonien und hilf uns!',
        10: 'Wie er aber die Vision (das Gesicht) sah, schlossen wir (legten wir uns zurecht) sofort, dass Gott uns berufen hatte, ihnen das Evangelium zu verkündigen.',
        11: 'Nachdem wir von Troas ausgelaufen waren, fuhren wir geradewegs nach Samothrake, am folgenden Tag {aber} nach Neapolis (Neustadt),',
        12: 'und von dort [gingen wir] nach Philippi, das eine Stadt des ersten Teils von Makedonien ist, eine Kolonie. Wir waren aber in dieser Stadt und verweilten (brachten zu, verbrachten) einige Tage.',
        13: 'Am Sabbat aber gingen wir zum Tor hinaus zum Fluss, wo wir eine Synagoge (Gebetsstätte) vermuteten, und nachdem wir uns gesetzt hatten sprachen wir mit den Frauen, die [dort] zusammengekommen waren.',
        14: '{Und} eine Frau namens Lydia, eine Purpurwollenhändlerin aus der Stadt Thyatira, eine Gottesfürchtige, hörte zu, der öffnete der Herr das Herz, (zu hören auf =) dass sie auf das hörte (achtete), was Paulus sagte.',
        15: 'Als sie aber getauft wurde und ihre Hausbewohner (ihre Familie), lud sie ein {indem sie/ und sprach}: Wenn ihr meint (überzeugt seid), dass ich an den Herrn gläubig bin, kommt in mein Haus und bleibt. Und sie drängte (nötigte) uns.',
        16: 'Es begab sich aber, als wir zur Synagoge gingen, begegnete uns (ging uns entgegen) eine Sklavin (Magd), die hatte einen Wahrsagegeist, brachte ihren Herren großen Verdienst ein, indem sie wahrsagte.',
        17: 'Die folge Paulus und uns und schrie {indem sie/ und sprach}: Diese Menschen sind Sklaven (Diener) des höchsten Gottes, die verkündigen euch den Weg der Rettung (den Heilsweg).',
        18: 'Das machte sie {aber} über viele Tage hin (viele Tage lang). Paulus aber regte [das] auf (war aufgebracht) und sich umdrehend sprach er zum Geist: Hiermit befehle ich dir im Namen Jesu Christi, von ihr zu verschwinden (auszufahren). Und er verschwand (fuhr aus) von ihr in dieser Stunde.',
        19: 'Als aber ihre Herren sahen, dass die Aussicht auf ihren Erwerb verschwunden war, ergriffen sie Paulus und Silas unds schleppten sie zum Marktplatz (Forum) zu den Behörden',
        20: 'und sprachen, als sie sie den Prätoren vorführten: Diese Menschen, die Juden sind, wiegeln unsere Stadt auf',
        21: 'und verkündigen Gesetze (Riten), die wir nicht bei uns, die wir Römer sind, gelten lassen noch tun dürfen.',
        22: 'Und das Volk erhob sich mit (ebenfalls) gegen sie und die Prätoren befahlen, nachdem sie ihnen die Kleider {ringsum} heruntergerissen hatten, die Prügelstrafe zu verabreichen',
        23: 'Nachdem man ihnen viele Schläge versetzt hatte, warfen sie sie ins Gefängnis und befahlen dem Gefängniswärter, sie sicher zu verwahren (gefangen zu halten).',
        24: 'Der, nachdem er eine solche Anweisung erhalten hatte, warf sie in das innere Gefängnis und schloss ihre Füße in den Block ein.',
        25: 'Aber um Mitternacht beteten Paulus und Silas und priesen (besangen, rühmten) Gott. Die Gefangenen aber hörten ihnen zu.',
        26: 'Plötzlich aber ereignete sich ein großes Erdbeben, sodass die Fundamente des Gefängnisses ins Wanken gerieten. Sofort aber wurden alle Türen geöffnet und die Fesseln aller gelöst.',
        27: 'Nachdem aber der Gefängniswärter wach geworden war und sah, dass die Türen des Gefängnisses geöffnet worden waren, zog er das Schwert und wollte sich töten, weil er meinte, die Gefangenen wären entflohen.',
        28: 'Paulus aber rief mit gewaltiger Stimme {und sprach}: Tu dir nichts Böses (Übles) an, wir sind doch alle hier.',
        29: 'Nachdem er Licht verlangt hatte, sprang er hinein und fiel Paulus und Silas zu Füßen, während ihn ein Zittern überfiel.',
        30: 'Nachdem er sie hinausgeführt hatte, sagte er: Ihr Herren, was muss ich tun, damit ich gerettet werde?',
        31: 'Sie aber sprachen: Glaube an den Herrn Jesus, und du wirst gerettet und deine Familie (deine Hausbewohner).',
        32: 'Und die sagten ihm das Wort des Herrn mit allen, die in seinem Haus [waren].',
        33: 'Und er nahm sie zu sich in jener nächtlichen Stunde (Stunde der Nacht), wusch ihnen die Striemen und wurde sofort getauft und alle die Seinen,',
        34: 'dann führte er sie hinauf ins Haus und setzte ihnen eine Mahlzeit vor und jubelte mit der ganzen Familie, dass er an Gott gläubig [geworden war].',
        35: 'Als es aber Tag geworden war, schickten die Prätoren die Liktoren {und sprachen}: Lasst jene Menschen frei!',
        36: 'Der Gefängniswärter meldete diese Worte dem Paulus: Die Prätoren haben geschickt: ihr sollt freigelassen werden (dass ihr freigelassen werdet). Geht also jetzt hinaus und zieht hin in Frieden.',
        37: 'Aber Paulus sprach zu ihnen: Sie haben uns öffentlich ohne Prozess verprügelt (die Prügelstrafe verabreicht), obwohl wir Römer sind, sie warfen uns ins Gefängnis, und jetzt entlassen sie uns heimlich? Oh nein! Vielmehr (sondern) sollen sie kommen und uns hinausgeleiten.',
        38: 'Die Liktoren {aber} meldeten (berichteten) den Prätoren diese Worte. Sie fürchteten sich aber, als sie hörten: Sie sind Römer,',
        39: 'und kamen und redeten ihnen gut zu (gaben ihnen gute Worte, sprachen ihnen freundlich zu) und führten sie hinaus. Dabei baten sie sie, die Stadt zu verlassen.',
        40: 'Nachdem sie aber das Gefängnis verlassen hatten (weggegangen waren vom Gefängnis) besuchten sie (traten sie ein bei) Lydia. Sie sahen die Brüder und trösteten sie (redeten ihnen gut zu) und gingen fort.',
    },
    17: {
        16: 'Als Paulus sie aber in Athen erwartete, geriet sein Geist in ihm in Wallung, weil er sah, dass die Stadt voller Götterbilder war.',
        17: 'Also unterredete er sich in der Synagoge mit den Juden und den Sebomenoi und auf dem Markt täglich mit den zufällig Anwesenden.',
        18: 'Aber auch einige von den Epikuräern und stoischen Philosophen unterredeten sich mit ihm und einige sagten: „Was dieser Schwätzer (Klugschwätzer) wohl sagen will?“Andere aber: „Er scheint ein Verkünder fremder Gottheiten zu sein“, weil er Jesus und die Auferstehung verkündigte.',
        19: 'Und nachdem sie ihn ergriffen hatten, nahmen sie ihn mit zum Areopag und sagten: Können wir wissen, welches jene neue Lehre ist, von der du redest?',
        20: 'Denn gewisse befremdliche Dinge bringst du uns zu Ohren. Wir wollen nun wissen, was dies sein mag.',
        21: 'Alle Athener aber und die sich aufhaltenden Fremden hatten zu nicht anderem Muße, als etwas Neues zu sagen oder zu hören.',
        22: 'Als Paulus aber in der Mitte des Areopag stand, sagte er: (Männer Athens =) Athener, ich beobachte (sehe), wie (dass) ihr durch und durch religiös seid.',
        23: 'Während ich nämlich [in Athen] umherging und mir eure Heiligtümer genau ansah, fand ich auch einen Altar, auf dem geschrieben steht: Dem unbekannten Gott. Was ihr nun unbekannter Weise anbetet (verehrt), das verkündige ich euch:',
        24: 'Der Gott, der die Welt gemacht hat und alles was in ihr ist, dieser Herr des Himmels und der Erde, wohnt nicht in von Hand gemachten Tempeln.',
        25: 'Auch wird er nicht von Menschenhänden bedient, weil er etwas bedarf; er selbst gibt allen Leben und Atem und alle Dinge (Alles).',
        26: 'Und er hat aus einem alle Völker der Menschen gemacht, dass sie die ganze Oberfläche der Erde bewohnen; er legte bestimmte Zeiten (= Jahreszeiten) fest und die Grenzen ihrer Wohnungen,',
        27: 'dass sie Gott suchen, ob sie ihn ertasten und finden möchten, denn jedenfalls nicht fern ist er von jedem von uns.',
        28: 'Denn in ihm leben wir, bewegen wir uns und sind wir, wie auch einige von euren Dichtern gesagt haben: „Denn wir sind auch sein Geschlecht“.',
        29: 'Weil wir nun Gottes Geschlecht sind (von Gott abstammen), dürfen wir nicht meinen, dass Goldenes oder Silbernes oder Steinernes, Gebilde menschlicher Kunst (fertigkeit) und Phantasie (Erfindungsgabe), dem Göttlichen gleich seien.',
        30: 'Nachdem Gott nun über diese Zeit der Unwissenheit hinweg gesehen hat, verkündigt er jetzt allen Menschen überall umzukehren,',
        31: 'weil er einen Tag festgesetzt hat, an dem er den Erdkreis in Gerechtigkeit richten will, durch einen Mann, den er ausersehen hat, indem er allen einen Beweis dadurch erbrachte, dass er ihn von den Toten auferweckte.',
        32: 'Als sie aber von der Auferstehung der Toten hörten, spotteten die einen, die anderen aber sprachen: Wir wollen dich darüber ein andernmal hören.',
        33: 'So ging Paulus aus ihrer Mitte weg.',
        34: 'Einige Männer aber schlossen sich ihm an und begannen zu glauben, unter ihnen auch Dionysios, der Areopagit, und eine Frau mit Namen Damaris, und andere mit ihnen.',
    },
    19: {
        1: 'Es geschah aber, während Apollos in Korinth war, dass Paulus die höher gelegenden Gegenden durchziehend [herab] kam nach Ephesus und einige Schüler (Jünger) fand.',
        2: 'Und er sprach zu ihnen: Habt ihr heiligen Geist empfangen, als ihr gläubig wurdet? Die aber zu ihm: Wenn wir doch aber nicht gehört haben, dass es heiligen Geist gibt?',
        3: 'Und er sprach: Auf was wurdet ihr denn getauft? Die aber sprachen: Auf die Taufe des Johannes.',
        4: 'Paulus aber sprach: Johannes taufte eine Taufe der Buße (Umkehr) dem Volk sagend, dass sie an den nach ihm Kommenden glauben sollten, dieses ist an Jesus.',
        5: 'Hörend aber (Als sie es aber aber hörten) wurden sie getauft auf den Namen des Herren Jesu.',
        6: 'Und als ihnen Paulus die Hände auflegte, kam der heilige Geist auf sie und sie begannen zu reden in Zungen und prophetisch zu reden.',
        7: 'Es waren aber alle Männer ungefähr zwölf.',
    },
    20: {
        16: 'Denn Paulus hatte es sich vorgenommen (entschieden), an Ephesus vorbei zu fahren, um keine Zeit in [der Provinz] Asien zu verlieren; denn er beeilte sich, um am Tag des Pfingstfestes in Jerusalem zu sein, wenn es [ihm] möglich ist.',
        17: 'Von Milet [aus] sandte er [eine Nachricht] nach Ephesus, um die Ältesten der Kirche zu sich kommen zu lassen.',
        18: "Als sie bei ihm angekommen waren, sagte er ihnen: „''Ihr'' wisst, wie von dem ersten Tag an, als ich Asien betrat, die ganze Zeit (immer) mit (bei) euch gewesen bin,",
        19: 'indem ich dem Herrn diente mit aller Demut (Bescheidenheit) und [unter] Tränen und Versuchungen (Prüfungen, Anfechtungen), die mir entgegentraten (begegneten) in den Anschlägen der Juden.',
        20: '[Ihr wisst auch,] wie ich nichts von dem zurückhielt (vorenthielt, verschwieg), was für euch hilfreich ist, indem ich es nicht verkündige. [Nein,] ich habe euch gelehrt öffentlich und in [euren] Häusern,',
        21: 'indem ich sowohl den Juden als auch den Griechen eindrücklich bezeugte, dass sie zu Gott umkehren und an unseren Herrn Jesus Christus glauben sollen.',
        22: 'Und nun, siehe, [weil] ich an den Geist gebunden (gefesselt) bin, gehe ich nach Jerusalem und weiß nicht, welche [Dinge] mir dort geschehen werden.',
        23: '[Ich weiß] nur, dass der Heilige Geist mir in jeder Stadt sagt, dass mich Fesseln und Bedrängnis erwarten.',
        24: 'Aber mein Leben ist nicht der Rede wert. Wenn ich nur meinen Lauf (Wettlauf) vollenden (beenden) könnte, den Dienst, den ich durch den Herrn Jesus bekommen habe: das Evangelium der Gnade Gottes zu bezeugen!',
        25: "Und nun, siehe, ''ich'' weiß (bin mir sicher), dass keiner mehr mein Angesicht sehen wird, ihr alle, unter denen ich das Königreich [Gottes] verkündet (gepredigt) habe.",
        26: 'Darum bezeuge ich an diesem Tag, dass ich rein (unschuldig) bin von dem Blut aller.',
        27: 'Denn ich habe nicht verschwiegen, sondern euch den ganzen Willen (Absicht, Plan) Gottes verkündet.',
        28: 'Richtet euren Sinn (Gebt acht) auf euch selbst und die ganze Herde, in der euch der Heiligen Geist zu Aufseher (Bischöfe, Hirten, Pastoren) bestellt hat, damit ihr die Gemeinde Gottes weidet (für sie sorgt), die er erwählt hat durch sein eigenes Blut.',
        29: "''Ich'' weiß, dass mit meiner Abreise [immer wieder] gefährliche Wölfe hereinbrechen werden in eurer [Mitte]. Sie werden die Herde nicht verschonen.",
        30: 'Und aus euch selbst (aus eurer Mitte) werden Menschen auftreten, die Verdrehtes reden, um die Jünger wegzuziehen hinter ihnen her.',
        31: 'Darum wachet; erinnert euch daran, dass ich drei Jahre lang Tag und Nacht nicht aufhörte, jeden von euch unter Tränen zu ermahnen.',
        32: 'Und nun vertraue ich euch Gott und dem Wort (Botschaft) seiner Gnade an, das kräftig (fähig) ist, [euch] aufzubauen und [euch] das Erbteil (Erbe) unter allen Geheiligten zu geben.',
        33: 'Silber oder Gold oder Kleidung habe ich von niemandem verlangt (begehrt).',
        34: 'Ihr selbst wisst, dass meinen Bedürfnissen und denen, die mit mir waren, diese meine Hände gedient haben.',
        35: "Alles habe ich euch gezeigt, dass während man arbeitet (sich abmüht), es notwendig ist, den Schwachen (Kranken) zu helfen und das Wort des Herrn Jesu zu erinnern, der selbst sagte: 'Geben ist seliger (macht glücklicher) als Nehmen.'“",
        36: 'Und als er das gesagt hatte, kniete er sich hin und betete mit ihnen allen.',
        37: 'Danach fingen alle laut (stark, viel) an zu weinen, sie fielen Paulus um den Hals und küssten ihn immer wieder.',
        38: 'Am meisten bekümmerte sie {das Wort}, dass er {ihnen} gesagt hatte, dass sie ihn nicht mehr persönlich sehen werden. Dann begleiteten sie ihn zum Schiff.',
    },
}
